:root {
  --color-primary-dark: #1a2a4a;
  --color-primary-darker: #101b33;
  --color-accent: #8a6d3b;
  --color-accent-on-dark: #d9c9a3;
  --color-bg: #ffffff;
  --color-bg-alt: #f5f3ef;
  --color-text: #222222;
  --color-text-light: #ffffff;
  --color-border: #d8d2c4;
  --font-serif: Georgia, 'Times New Roman', serif;
  --font-sans: 'Trebuchet MS', Verdana, sans-serif;
  --space-xs: 0.5rem;
  --space-sm: 1rem;
  --space-md: 2rem;
  --space-lg: 3rem;
  --max-width: 75rem;
}

* {
  box-sizing: border-box;
}

html {
  font-size: 100%;
}

body {
  margin: 0;
  font-family: var(--font-sans);
  color: var(--color-text);
  background-color: var(--color-bg);
  line-height: 1.6;
}

h1, h2, h3 {
  font-family: var(--font-serif);
  color: var(--color-primary-dark);
  line-height: 1.25;
  margin-top: 0;
}

p {
  margin-top: 0;
}

a {
  color: var(--color-primary-dark);
  text-decoration: underline;
}

a:hover {
  color: var(--color-accent);
}

a:focus-visible,
button:focus-visible,
input:focus-visible,
textarea:focus-visible {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

.container {
  width: 100%;
  max-width: var(--max-width);
  margin-left: auto;
  margin-right: auto;
  padding-left: 1.25rem;
  padding-right: 1.25rem;
}

/* Header */
header {
  background-color: var(--color-bg);
  border-bottom: 1px solid var(--color-border);
  padding: var(--space-sm) 0;
}

.header-inner {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-sm);
}

.logo {
  font-family: var(--font-serif);
  text-transform: uppercase;
  font-size: clamp(0.95rem, 2.5vw, 1.3rem);
  letter-spacing: 0.2em;
  color: var(--color-primary-dark);
  text-decoration: none;
  border-top: 3px double var(--color-accent);
  border-bottom: 3px double var(--color-accent);
  padding: 0.3rem 0.6rem;
  display: inline-block;
  max-width: 100%;
  word-break: break-word;
}

.logo:hover {
  color: var(--color-accent);
}

nav[aria-label="Main"] .nav-list {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-sm);
  margin: 0;
  padding: 0;
}

nav[aria-label="Main"] a {
  text-decoration: none;
  color: var(--color-primary-dark);
  font-weight: 700;
  padding: 0.5rem 0.25rem;
  display: inline-block;
}

nav[aria-label="Main"] a:hover {
  color: var(--color-accent);
  text-decoration: underline;
}

/* Footer */
footer {
  background-color: var(--color-primary-dark);
  color: var(--color-text-light);
  padding: var(--space-md) 0;
  margin-top: var(--space-lg);
}

footer p {
  margin: 0.25rem 0;
  font-size: 0.95rem;
}

.footer-name {
  font-family: var(--font-serif);
  color: var(--color-accent-on-dark);
  font-weight: 700;
  letter-spacing: 0.05em;
  margin-bottom: var(--space-xs);
}

footer a {
  color: var(--color-accent-on-dark);
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  padding: 0.75rem 1.5rem;
  background-color: var(--color-primary-dark);
  color: var(--color-text-light);
  border: 2px solid var(--color-primary-dark);
  border-radius: 0.25rem;
  font-family: var(--font-sans);
  font-weight: 700;
  font-size: 1rem;
  text-decoration: none;
  cursor: pointer;
  transition: background-color 0.2s ease, color 0.2s ease;
}

.btn:hover {
  background-color: var(--color-text-light);
  color: var(--color-primary-dark);
}

.btn-outline {
  background-color: transparent;
  color: var(--color-primary-dark);
}

.btn-outline:hover {
  background-color: var(--color-primary-dark);
  color: var(--color-text-light);
}

/* Cards */
.card {
  background-color: var(--color-bg-alt);
  border: 1px solid var(--color-border);
  border-radius: 0.5rem;
  padding: var(--space-md);
  height: 100%;
}

.card h3 {
  margin-bottom: var(--space-xs);
}

/* Grid helper */
.grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-md);
}

/* Sections */
section {
  padding: var(--space-lg) 0;
}

.section-alt {
  background-color: var(--color-bg-alt);
}

/* Forms */
form {
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
  max-width: 40rem;
}

.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

label {
  font-weight: 700;
  color: var(--color-primary-dark);
}

input,
textarea,
select {
  min-height: 44px;
  padding: 0.6rem 0.75rem;
  border: 1px solid var(--color-border);
  border-radius: 0.25rem;
  font-family: var(--font-sans);
  font-size: 1rem;
  color: var(--color-text);
  background-color: var(--color-bg);
}

textarea {
  min-height: 8rem;
  resize: vertical;
}

input:focus,
textarea:focus,
select:focus {
  border-color: var(--color-accent);
}

/* Responsive breakpoints */
@media (max-width: 600px) {
  .header-inner {
    flex-direction: column;
    align-items: flex-start;
  }

  nav[aria-label="Main"] .nav-list {
    flex-direction: column;
    gap: 0.25rem;
    width: 100%;
  }

  section {
    padding: var(--space-md) 0;
  }

  .btn {
    width: 100%;
  }
}

@media (min-width: 601px) {
  .grid-2 {
    grid-template-columns: repeat(2, 1fr);
  }

  .grid-3 {
    grid-template-columns: repeat(3, 1fr);
  }

  .header-inner {
    flex-wrap: nowrap;
  }
}

@media (prefers-reduced-motion: reduce) {
  * {
    animation: none !important;
    transition: none !important;
  }
}

