    flex-direction: row;
    justify-content: center;
  }

  .index-cta-actions .btn {
    width: auto;
  }
}

.expertise-card p {
  margin-bottom: var(--space-xs);
}

.expertise-services-label {
  font-weight: 700;
  color: var(--color-primary-dark);
  margin-bottom: 0.25rem;
}

.expertise-services {
  margin: 0;
  padding-left: 1.25rem;
  color: var(--color-text);
}

.expertise-services li {
  margin-bottom: 0.25rem;
}

@media (max-width: 600px) {
  .expertise-card {
    padding: var(--space-sm);
  }
}

@media (min-width: 601px) {
  #areas .grid-3 {
    align-items: stretch;
  }
}

.about-story {
  display: grid;
  grid-template-columns: 1fr;
  gap: var(--space-md);
  align-items: center;
}

.about-story-figure {
  margin: 0;
  text-align: center;
}

.about-story-img {
  width: 100%;
  max-width: 20rem;
  height: auto;
  border-radius: 0.5rem;
  border: 1px solid var(--color-border);
  display: block;
  margin: 0 auto var(--space-xs);
}

.about-story-figure figcaption {
  font-family: var(--font-serif);
  color: var(--color-accent);
  font-size: 0.95rem;
}

.about-timeline {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: var(--space-md);
  border-left: 3px solid var(--color-accent);
  padding-left: var(--space-md);
}

.about-timeline-item {
  position: relative;
}

.about-timeline-item::before {
  content: "";
  position: absolute;
  left: calc(-1 * var(--space-md) - 0.4rem);
  top: 0.4rem;
  width: 0.8rem;
  height: 0.8rem;
  border-radius: 50%;
  background-color: var(--color-primary-dark);
}

.about-timeline-year {
  display: inline-block;
  font-family: var(--font-serif);
  font-weight: 700;
  color: var(--color-primary-dark);
  margin-bottom: 0.25rem;
}

.about-timeline-content h3 {
  margin-bottom: 0.25rem;
}

.about-values-grid {
  margin-top: var(--space-md);
}

@media (min-width: 601px) {
  .about-story {
    grid-template-columns: 2fr 1fr;
  }

  .about-story-figure {
    order: 2;
  }

  .about-story-text {
    order: 1;
  }
}

@media (max-width: 600px) {
  .about-timeline {
    padding-left: var(--space-sm);
  }

  .about-timeline-item::before {
    left: calc(-1 * var(--space-sm) - 0.4rem);
  }
}

.contact-info-grid .card p {
  margin: 0;
}

.contact-hours-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: var(--space-sm);
  background-color: var(--color-bg);
  border: 1px solid var(--color-border);
}

.contact-hours-caption {
  text-align: left;
  font-weight: 700;
  color: var(--color-primary-dark);
  margin-bottom: var(--space-xs);
  font-family: var(--font-serif);
}

.contact-hours-table th,
.contact-hours-table td {
  text-align: left;
  padding: 0.75rem 1rem;
  border-bottom: 1px solid var(--color-border);
}

.contact-hours-table thead th {
  background-color: var(--color-primary-dark);
  color: var(--color-text-light);
}

.contact-hours-table tbody th {
  font-weight: 700;
  color: var(--color-primary-dark);
}

.contact-form {
  width: 100%;
}

@media (max-width: 600px) {
  .contact-hours-table th,
  .contact-hours-table td {
    padding: 0.5rem 0.6rem;
    font-size: 0.9rem;
  }
}

@media (min-width: 601px) {
  .contact-form {
    max-width: 40rem;
  }
}

